import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.CFuv5BrO.js";const g=JSON.parse('{"title":"Stage 0 · 定义与原型","description":"Hearth Stage 0 开发模块：产品楔子、真实任务基线、可点击原型、协议契约、评测与安全工程基线。","frontmatter":{"title":"Stage 0 · 定义与原型","description":"Hearth Stage 0 开发模块：产品楔子、真实任务基线、可点击原型、协议契约、评测与安全工程基线。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-0.md","filePath":"delivery/stage-0.md","lastUpdated":null}'),i={name:"delivery/stage-0.md"};function o(d,t,n,s,h,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<p class="eyebrow">MODULE 0 / 7</p><h1 id="stage-0-·-定义与原型" tabindex="-1">Stage 0 · 定义与原型 <a class="header-anchor" href="#stage-0-·-定义与原型" aria-label="Permalink to &quot;Stage 0 · 定义与原型&quot;">​</a></h1><p class="lead">先把“为谁做、做什么、怎么验收”钉死，再开始写真实执行内核。Stage 0 的产物必须足以支撑第一个可运行纵向切片，而不是一堆无法落地的概念文档。</p><h2 id="本模块要回答" tabindex="-1">本模块要回答 <a class="header-anchor" href="#本模块要回答" aria-label="Permalink to &quot;本模块要回答&quot;">​</a></h2><ul><li>谁是首位真实用户，第一个高频、可验收的任务楔子是什么？</li><li>Hearth 与直接使用 Codex、聊天助手或自动化脚本相比，独立价值在哪里？</li><li>任务在创建、执行、审批、失败和恢复时，用户分别看到什么？</li><li>前后端、执行器、审批和评测依赖哪些稳定契约？</li></ul><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>一个空仓库，以及一位愿意提供真实任务和反馈的首位用户。</li><li>可以记录全人工基线与直接使用 Codex 的基线。</li><li>暂不接入真实高风险外部副作用。</li></ul><h2 id="开发步骤" tabindex="-1">开发步骤 <a class="header-anchor" href="#开发步骤" aria-label="Permalink to &quot;开发步骤&quot;">​</a></h2><ol><li><strong>锁定产品楔子。</strong> 选定首位用户、第一个任务族和明确非目标；写出一句话定位与“不做什么”清单。</li><li><strong>建立真实任务集。</strong> 收集 20–30 个真实任务，筛出至少 12 个有输入、产物和验收方式的任务，覆盖成功、失败、等待审批和需要接管。</li><li><strong>跑基线。</strong> 记录全人工与直接使用 Codex 的人工分钟、成功率、Token、错误类型和用户不满点。</li><li><strong>画端到端原型。</strong> 覆盖今日、需要你、产物、设置四个入口，以及排队、执行、审批、需要信息、完成、失败和可恢复状态。</li><li><strong>定义核心契约。</strong> 固定 Task、Ticket、Run、Event、Executor、Approval、Artifact、Receipt、Budget 的字段和状态迁移；定义 Task Pack、Result、失败分类与 UI 投影。</li><li><strong>搭工程骨架。</strong> 初始化 monorepo、类型检查、lint、测试、CI、ADR 模板、文档目录和 fake executor。</li><li><strong>建立评测与安全基线。</strong> 为 12 个任务建立 runner、评分与人工复核；完成威胁模型、风险分级、审批矩阵和秘密处理规则。</li><li><strong>做契约演练。</strong> 用 mock server 驱动完整原型流程，确认同一事件流可以重建页面状态，未知状态不会伪装成成功。</li></ol><h2 id="增量拆分" tabindex="-1">增量拆分 <a class="header-anchor" href="#增量拆分" aria-label="Permalink to &quot;增量拆分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>增量</th><th>用户可见结果</th><th>完成证据</th></tr></thead><tbody><tr><td>D0.1 产品楔子与任务基线</td><td>能解释首批用户为什么使用 Hearth</td><td>12+ 个真实任务、双基线、非目标与成功指标</td></tr><tr><td>D0.2 端到端原型</td><td>不读说明也能创建任务、审批、查看产物和恢复</td><td>桌面/手机原型、全部状态、可用性走查</td></tr><tr><td>D0.3 协议与数据契约</td><td>原型状态都能映射到稳定字段和事件</td><td>实体定义、状态机、投影契约、契约测试</td></tr><tr><td>D0.4 评测、安全与工程基线</td><td>每个后续增量从第一天就能被验证</td><td>评测 runner、威胁模型、审批矩阵、CI、fake executor</td></tr></tbody></table><h2 id="退出验收" tabindex="-1">退出验收 <a class="header-anchor" href="#退出验收" aria-label="Permalink to &quot;退出验收&quot;">​</a></h2><ul><li>[ ] 至少 12 个任务有明确输入、产物、验收标准和失败样本。</li><li>[ ] 新用户可以在原型中完成主路径，每个状态只有一个主动作。</li><li>[ ] 页面不依赖内部数据库字段，事件流能重建 UI 投影。</li><li>[ ] 高风险动作已有审批路径；评测可重复运行；CI 能拦截契约和 schema 回归。</li><li>[ ] fake executor 能驱动完整 UI 流程，且没有真实外部副作用。</li></ul><h2 id="本模块不做" tabindex="-1">本模块不做 <a class="header-anchor" href="#本模块不做" aria-label="Permalink to &quot;本模块不做&quot;">​</a></h2><ul><li>不先做完整内核再补界面。</li><li>不接入真实发送、支付、删除或系统设置修改。</li><li>不用“文档已写完”代替可点击原型和可重复评测。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>进入 <a href="/hearth-os/delivery/stage-1.html">Stage 1 · 持久内核与 MVP</a>，先交付可运行走路骨架，再收口 MVP-1。</p>',17)])])}const p=a(i,[["render",o]]);export{g as __pageData,p as default};
